import { weekRange } from "@me/date-range";
import { t } from "../../wording/t.ts";
import styles from "./home.module.css";

type Row = {
  id: string;
  title: string;
  startLocal: string;
  remindMinutes: number;
  reminderStatus: "none" | "scheduled" | "failed";
};

const REMIND = ["0", "10", "30", "60"] as const;
const remindLabel = (v: string) =>
  v === "0"
    ? t("home.label.remind-none")
    : v === "10"
    ? t("home.label.remind-10")
    : v === "30"
    ? t("home.label.remind-30")
    : t("home.label.remind-60");

const dayOf = (startLocal: string) => startLocal.slice(0, 10);
const timeOf = (startLocal: string) => startLocal.slice(11, 16);
const localDay = (d: Date) =>
  `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${
    String(d.getDate()).padStart(2, "0")
  }`;
const dayFormat = new Intl.DateTimeFormat(undefined, {
  weekday: "long",
  month: "short",
  day: "numeric",
});
const shortFormat = new Intl.DateTimeFormat(undefined, {
  month: "short",
  day: "numeric",
});
const dayLabel = (day: string) => {
  const [y, m, d] = day.split("-").map(Number);
  return dayFormat.format(new Date(y, m - 1, d));
};

function rowsOf(value: unknown): Row[] {
  const rows = (value as { rows?: Row[] } | null)?.rows;
  return Array.isArray(rows) ? rows : [];
}

function ReminderMark({ status }: { status: Row["reminderStatus"] }) {
  if (status === "scheduled") {
    return (
      <span role="img" aria-label={t("home.label.status-scheduled")}>
        <Icon icon={BellRing} pixels={16} />
      </span>
    );
  }
  if (status === "failed") {
    return (
      <span role="img" aria-label={t("home.label.status-failed")}>
        <Icon icon={CircleAlert} pixels={16} />
      </span>
    );
  }
  return null;
}

export function App() {
  const space = useContainerSpace();
  const [weekOffset, setWeekOffset] = useState(0);
  const [rows, setRows] = useState<Row[] | null>(null);
  const [failed, setFailed] = useState(false);
  const [adding, setAdding] = useState(false);
  const [removing, setRemoving] = useState<Row | null>(null);
  const list = useTool({ name: "event.list" });

  const load = useCallback(async () => {
    setFailed(false);
    if (space === "card") {
      const [a, b] = await Promise.all(
        [0, 1].map((n) =>
          appBridge()?.callTool("event.list", { weekOffset: n }).catch(() =>
            null
          )
        ),
      );
      if (!a) return setFailed(true);
      const now = `${localDay(new Date())}T00:00`;
      setRows(
        [...rowsOf(a), ...rowsOf(b)].filter((r) => r.startLocal >= now).slice(
          0,
          3,
        ),
      );
      return;
    }
    const result = await list.run({ weekOffset });
    if (result?.ok) setRows(rowsOf(result.value));
    else if (result) setFailed(true);
  }, [weekOffset, space]);

  useEffect(() => {
    void load();
  }, [load]);

  const range = weekRange(new Date(), weekOffset);
  const last = new Date(
    range.to.getFullYear(),
    range.to.getMonth(),
    range.to.getDate() - 1,
  );
  const today = localDay(new Date());

  const groups = new Map<string, Row[]>();
  for (const row of rows ?? []) {
    const day = dayOf(row.startLocal);
    groups.set(day, [...(groups.get(day) ?? []), row]);
  }

  const addButton = (
    <IconButton
      icon={Plus}
      label={t("home.button.add")}
      onClick={() => setAdding(true)}
    />
  );

  let body;
  if (failed) {
    body = (
      <ErrorState
        target={t("home.name.target")}
        onRetry={() => void load()}
      />
    );
  } else if (rows === null) {
    body = (
      <Loading loading placeholder={<Skeleton lines={4} />}>{null}</Loading>
    );
  } else if (rows.length === 0) {
    body = space === "card"
      ? <p className={styles.note}>{t("home.card.empty")}</p>
      : (
        <EmptyState
          icon={CalendarDays}
          message={t("home.empty.week")}
          action={{
            label: t("home.button.empty-add"),
            onSelect: () => setAdding(true),
          }}
        />
      );
  } else {
    body = (
      <div>
        {[...groups].map(([day, items]) => (
          <section key={day}>
            <h2 className={styles.day} data-today={day === today || undefined}>
              {day === today
                ? t("home.label.day-today", { day: dayLabel(day) })
                : t("home.label.day-other", { day: dayLabel(day) })}
            </h2>
            {items.map((row) => (
              <div className={styles.row} key={row.id}>
                <span className={styles.time}>{timeOf(row.startLocal)}</span>
                <span className={styles.name}>{row.title}</span>
                <ReminderMark status={row.reminderStatus} />
                {space !== "card" && (
                  <IconButton
                    icon={Trash2}
                    label={t("home.button.delete")}
                    variant="ghost"
                    onClick={() => setRemoving(row)}
                  />
                )}
              </div>
            ))}
          </section>
        ))}
      </div>
    );
  }

  return (
    <AppShell
      title={t("common.title.app")}
      actions={space === "card" ? undefined : addButton}
    >
      {space !== "card" && (
        <div className={styles.nav}>
          <IconButton
            icon={ChevronLeft}
            label={t("home.button.previous")}
            onClick={() => setWeekOffset(weekOffset - 1)}
          />
          {space === "full" && (
            <Button onClick={() => setWeekOffset(0)}>
              {t("home.button.this-week")}
            </Button>
          )}
          <IconButton
            icon={ChevronRight}
            label={t("home.button.next")}
            onClick={() => setWeekOffset(weekOffset + 1)}
          />
          <span className={styles.range}>
            {t("home.label.range", {
              from: shortFormat.format(range.from),
              to: shortFormat.format(last),
            })}
          </span>
        </div>
      )}
      {body}
      {adding && (
        <AddForm
          sheet={space !== "full"}
          onClose={() => setAdding(false)}
          onSaved={() => {
            setAdding(false);
            void load();
          }}
        />
      )}
      {removing && (
        <RemoveConfirm
          row={removing}
          onClose={() => setRemoving(null)}
          onDone={() => {
            setRemoving(null);
            void load();
          }}
        />
      )}
    </AppShell>
  );
}

